ets this container, and all its children, to be visible.\n108|func (c *Container) Show() {\n109|\tif !c.Hidden {\n110|\t\treturn\n111|\t}\n112|\n113|\tc.Hidden = false\n114|}\n115|\n116|// Hide sets this container, and all its children, to be not visible.\n117|func (c *Container) Hide() {\n118|\tif c.Hidden {\n119|\t\treturn\n120|\t}\n121|\n122|\tc.Hidden = true\n123|}\n124|\n125|// Refresh causes this object to be redrawn in it's current state\n126|func (c *Container) Refresh() {\n127|\tc.layout()\n128|\n129|\tfor _, child := range c.Objects {\n130|\t\tchild.Refresh()\n131|\t}\n132|\n133|\t// this is basically just canvas.Refresh(c) without the package loop\n134|\to := CurrentApp().Driver().CanvasForObject(c)\n135|\tif o == nil {\n136|\t\treturn\n137|\t}\n138|\to.Refresh(c)\n139|}\n140|\n141|// Remove updates the contents of this container to no longer include the specified object.\n142|// This method is not intended to be used inside a loop, to remove all the elements.\n143|// It is much more efficient to just set .Objects to nil instead.\n144|func (c *Container) Remove(rem CanvasObject) {\n145|\tif len(c.Objects) == 0 {\n146|\t\treturn\n147|\t}\n148|\n149|\tfor i, o := range c.Objects {\n150|\t\tif o != rem {\n151|\t\t\tcontinue\n152|\t\t}\n153|\n154|\t\tremoved := make([]CanvasObject, len(c.Objects)-1)\n155|\t\tcopy(removed, c.Objects[:i])\n156|\t\tcopy(removed[i:], c.Objects[i+1:])\n157|\n158|\t\tc.Objects = removed\n159|\t\tc.layout()\n160|\t\treturn\n161|\t}\n162|}\n163|\n164|// Visible returns true if the container is currently visible, false otherwise.\n165|func (c *Container) Visible() bool {\n166|\treturn !c.Hidden\n167|}\n168|\n169|func (c *Container) layout() {\n170|\tif c.Layout != nil {\n171|\t\tc.Layout.Layout(c.Objects, c.size)\n172|\t\treturn\n173|\t}\n174|}"}], "task_turn": 2, "text": "<summary>Exploring Fyne codebase structure. Checking existing interfaces and files mentioned in roadmap before implementation.</summary>\n\nLet me examine the curre