// Color returns the theme's color for the specified name and variant
func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	var hexStr string
	var found bool

	if variant == VariantDark && t.colorsDark != nil {
		hexStr, found = t.colorsDark[string(name)]
	} else if variant == VariantLight && t.colorsLight != nil {
		hexStr, found = t.colorsLight[string(name)]
	}

	// Fall back to generic colors
	if !found && t.colors != nil {
		hexStr, found = t.colors[string(name)]
	}

	// Parse hex color if found
	if found {
		c, err := parseHexColor(hexStr)
		if err == nil {
			return c
		}
	}

	// Fall back to default theme
	return t.fallback.Color(name, variant)
}

