package binding

import "fmt"

// stringFromSprintf creates a formatted string binding from multiple data items
type stringFromSprintf struct {
	base

	format  string
	sources []DataItem
}

// NewSprintf creates a new String binding that formats values from multiple source data items
// using fmt.Sprintf with the given format string. The binding updates automatically when any source changes.
// This is useful for combining or formatting data bindings dynamically.
//
// Example:
//   name := binding.NewString()
//   age := binding.NewInt()
//   label := binding.NewSprintf("Name: %s, Age: %d", name, age)
//
// Since: 2.2
func NewSprintf(format string, b ...DataItem) String {
	if len(b) == 0 {
		return NewString()
	}

	str := &stringFromSprintf{
		format:  format,
		sources: b,
	}

	// Listen to all source data items
	for _, source := range b {
		if source != nil {
			source.AddListener(str)
		}
	}

	return str
}

// extractValue extracts the underlying value from a DataItem
func extractValue(item DataItem) (interface{}, error) {
	if item == nil {
		return nil, fmt.Errorf("nil data item")
	}

	switch v := item.(type) {
	case String:
		return v.Get()
	case Int:
		return v.Get()
	case Float:
		return v.Get()
	case Bool:
		return v.Get()
	case Rune:
		return v.Get()
	case Bytes:
		return v.Get()
	case URI:
		return v.Get()
	case Untyped:
		return v.Get()
	default:
		return nil, fmt.Errorf("unsupported binding type: %T", item)
	}
}

func (s *stringFromSprintf) Get() (string, error) {
	// Extract values from all sources
	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		val, err := extractValue(source)
		if err != nil {
			return "", err
		}
		values[i] = val
	}

	// Format the string with all values
	return fmt.Sprintf(s.format, values...), nil
}

func (s *stringFromSprintf) Set(string) error {
	return fmt.Errorf("sprintf bindings are read-only")
}

func (s *stringFromSprintf) DataChanged() {
	s.trigger()
}

// StringToStringWithFormat creates a binding that connects a String data item to another String
// with formatting applied. Changes to the source String will be formatted and pushed to the result.
// This is a convenience wrapper around NewSprintf for string-to-string formatting.
//
// Example:
//   name := binding.NewString()
//   greeting := binding.StringToStringWithFormat(name, "Hello, %s!")
//
// Since: 2.2
func StringToStringWithFormat(source String, format string) String {
	return NewSprintf(format, source)
}

